 const f=document.getElementById('admin-import');if(f)f.onsubmit=e=>{e.preventDefault();act(async()=>{const data=new FormData(f);const files=data.getAll('file');data.delete('file');for(const file of files)data.append('files',file);data.set('request_key',f.dataset.requestKey||crypto.randomUUID());f.dataset.requestKey=data.get('request_key');data.set('reuse_confirmed','true');await request('/admin/imports/batch',{method:'POST',body:data});f.dataset.requestKey='';await loadAdmin();adminPage();say('已加入可恢复导入队列。');});};
