 for(const el of document.querySelectorAll('[data-bank-page]'))el.onclick=()=>act(async()=>{adminFilters.offset=Number(el.dataset.bankPage);await loadAdmin();adminPage();document.getElementById('admin-bank-results')?.scrollIntoView();});
 for(const el of document.querySelectorAll('[data-admin-types]'))el.onclick=()=>{const q=adminQuestions.find(q=>q.question_id===el.dataset.adminTypes);editor('核对解题类型',`<p class="muted">按解题必需步骤和模型核对，不能只匹配题干关键词；不能确认可全部留空。知识点仍使用学习路径注册表。</p>${[['methods','解题方法'],['structures','题目模型']].map(([field,title])=>`<fieldset><legend>${title} · 可多选</legend>${Object.entries(registry.question_types[field]).map(([id,name])=>`<label class="check"><input type="checkbox" name="${field}" value="${esc(id)}" ${q.types[field].includes(id)?'checked':''}>${esc(name)}</label>`).join('')}</fieldset>`).join('')}<label>核对依据<textarea name="reason" required maxlength="2000" placeholder="说明解题需要哪些步骤、哪些物理模型"></textarea></label>`,f=>request('/admin/questions/'+q.question_id+'/types',{method:'PUT',body:{methods:f.getAll('methods'),structures:f.getAll('structures'),reason:f.get('reason'),expected_version:q.version_id,expected_classification_id:q.classification_id}}));};
 for(const el of document.querySelectorAll('[data-type-history]'))el.onclick=()=>act(async()=>{const rows=await request('/admin/questions/'+el.dataset.typeHistory+'/types'),d=document.createElement('dialog');d.innerHTML=`<h2>题型修订记录</h2>${rows.map(r=>`<article><small>${new Date(r.at).toLocaleString()} · ${esc(r.version_id)}</small><div>${typeLabels({types:r})||'保留未分类'}</div><p>${esc(r.reason)}</p></article>`).join('')||'<p>暂无人工修订，自动标签未作为人工核对记录。</p>'}<button class="as-btn" data-close>关闭</button>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>{d.close();d.remove();};d.showModal();});
 for(const [attr,path] of [['data-publish-batch','publish-batch'],['data-retry-batch','retry'],['data-reparse-batch','reparse']])for(const el of document.querySelectorAll('['+attr+']'))el.onclick=()=>act(async()=>{const id=el.getAttribute(attr);const data=await request(path==='publish-batch'?'/admin/publish-batch/'+id:'/admin/imports/'+id+'/'+path,{method:'POST'});await loadAdmin();adminPage();say(path==='publish-batch'?`发布 ${data.published.length} 题，${data.skipped.length} 题需处理异常。`:'任务已重新入队，原文件与题目记录保留。');});
 for(const el of document.querySelectorAll('[data-admin-tags]'))el.onclick=()=>{const q=adminQuestions.find(q=>q.question_id===el.dataset.adminTags);editor('核心与关联 Topic',`<p class="muted">只标注解题必需的核心知识；无法确认可留空。</p><label>核心 Topic（逗号分隔）<input name="core" value="${esc(q.topics.core.join(','))}" placeholder="2.5, 3.3"></label><label>关联 Topic（逗号分隔）<input name="related" value="${esc(q.topics.related.join(','))}"></label><details><summary>查看现有知识点注册表</summary>${allTopics().map(t=>`<div>${t.topic_id} ${esc(t.title)}</div>`).join('')}</details>`,f=>request('/admin/questions/'+q.question_id+'/tags',{method:'PUT',body:{course_id:registry.course_id,core:String(f.get('core')).split(/[,，\s]+/).filter(Boolean),related:String(f.get('related')).split(/[,，\s]+/).filter(Boolean)}}));};
 for(const el of document.querySelectorAll('[data-admin-answer]'))el.onclick=()=>{const q=adminQuestions.find(q=>q.question_id===el.dataset.adminAnswer);editor('修订标准答案',`<label>正确选项<select name="label">${q.options.map(o=>`<option ${q.answer?.label===o.label?'selected':''}>${o.label}</option>`).join('')}</select></label><label>可核查的来源与解析<textarea name="reason" required></textarea></label><p class="muted">新建答案版本，历史学生作答和原评分保留。需要重评分时使用管理员成绩修订接口。</p>`,f=>request('/admin/questions/'+q.question_id+'/answer',{method:'POST',body:{label:f.get('label'),reason:f.get('reason'),expected_revision:q.answer?.revision||0}}));};
 for(const el of document.querySelectorAll('[data-admin-edit]'))el.onclick=()=>{const q=adminQuestions.find(q=>q.question_id===el.dataset.adminEdit);editor('修订题目内容',`<label>题干<textarea name="stem" required>${esc(q.stem)}</textarea></label>${q.options.map(o=>`<label>选项 ${o.label}<textarea name="option-${o.label}" required>${esc(optionCaption(q,o))}</textarea></label>`).join('')}<p class="muted">将创建新题目版本并撤回发布。修改后重新核对原图、答案和标签。</p>`,f=>request('/admin/questions/'+q.question_id,{method:'PATCH',body:{expected_version:q.version_id,stem:f.get('stem'),options:q.options.map(o=>({label:o.label,text:f.get('option-'+o.label)}))}}));};
 for(const el of document.querySelectorAll('[data-admin-withdraw]'))el.onclick=()=>act(async()=>{await request('/admin/questions/'+el.dataset.adminWithdraw+'/withdraw',{method:'POST'});await loadAdmin();adminPage();});
 for(const el of document.querySelectorAll('[data-admin-publish]'))el.onclick=()=>{const q=adminQuestions.find(q=>q.question_id===el.dataset.adminPublish);editor('发布题目',`<p>原题 ${esc(q.source_number)} · ${q.meta.issues?.length?esc(q.meta.issues.join('，')):'结构检查合格'}</p><label class="check"><input type="checkbox" name="review" required>我已核对原图、完整选项、共用题干与答案来源</label>`,()=>request('/admin/questions/'+q.question_id+'/publish',{method:'POST',body:{acknowledge_issues:true}}));};
