function typeLabels(q){const names={...registry.question_types.methods,...registry.question_types.structures};return [...new Set([...(q.types?.methods||[]),...(q.types?.structures||[])])].filter(x=>names[x]).map(x=>`<span class="as-tag">题型 · ${esc(names[x])}</span>`).join('');}
function diagnosticHTML(f){
 const d=f.diagnostics;if(!d)return '';
 const stages={upload:'上传与文件保存',pdf_read:'页面读取',text_extraction:'文字提取 / 图片文字识别',question_detection:'题号识别',option_split:'题干与选项切分',database_write:'数据库写入',structure_validation:'结构校验',exam_admission:'考试准入',task_status_update:'任务状态更新'};
 const failed=d.failure_stage||d.exception?.stage;
 return `${failed?`<p class="as-import-error">阻断阶段：${esc(stages[failed]||failed)}</p>`:''}<details><summary>解析诊断${d.failure_stage?' · 阻断阶段：'+esc(stages[d.failure_stage]||d.failure_stage):''}</summary><p>原文件${d.upload?.persisted?'已保存':'保存未确认'} · 页面 ${d.pdf_read?.pages??'未读出'} · 原生文字 ${d.text_extraction?.native_characters??0} 字符</p><p>题号候选 ${d.question_detection?.candidates??0} · 成功切题 ${d.option_split?.passed??0} · 切分拒绝 ${d.option_split?.rejected??0} · 可作答 ${d.structure_validation?.passed??0} · 结构拒绝 ${d.structure_validation?.rejected??0}</p><p>数据库：${d.database_write?.success?'已写入 '+d.database_write.question_count+' 道题':d.exception?.stage==='database_write'?'写入失败':'尚未写入'}</p>${d.exception?`<p>异常阶段：${esc(stages[d.exception.stage]||d.exception.stage)} · ${esc(d.exception.type)} · ${esc(d.exception.message)}</p>`:''}<ul>${(d.candidates||[]).map(c=>`<li>第 ${esc(c.number)} 题 · 页 ${c.pages.join('、')} · 选项 ${c.labels.join(' / ')||'未切出'}${c.status==='rejected'?' · 拒绝：'+esc(c.reason):''}</li>`).join('')}${(d.structure_validation?.questions||[]).filter(q=>q.reasons.length).map(q=>`<li>第 ${esc(q.number)} 题结构待复核：${q.reasons.map(esc).join('、')}</li>`).join('')}</ul></details>`;
}
function ownJobsHTML(){
 const status={queued:'等待解析',running:'正在解析',completed:'解析完成',failed:'解析失败',partial:'部分完成',needs_review:'需要人工复核',imported:'已导入'};
 return `<div class="as-row"><h2>我的解析任务</h2>${button('刷新解析进度','data-own-refresh')}</div>${ownImports.map(b=>`<article class="as-row"><div><b>${esc(b.files.map(f=>f.filename).join('、'))}</b><p class="muted">${esc(status[b.status]||b.status)}</p>${b.files.map(f=>`${progressHTML(f)}${diagnosticHTML(f)}${f.error?`<p class="as-import-error" role="alert">${esc(f.error)}</p>`:(!f.question_ids?.length&&f.status==='needs_review'?`<p class="as-import-error">${f.warnings?.some(w=>w.includes('ocr_unavailable_or_failed'))?'扫描图片未能识别文字。请改传可选择文字的 PDF，或先完成图片文字识别。':'尚未识别出完整选择题，请检查题号、选项及页面是否齐全。原文件已保留。'}</p>`:'')}<p>${f.summary?`识别 ${f.summary.mcq} 道选择题 · 可作答 ${f.summary.structure_ready} 道 · 待复核 ${f.summary.exceptions} 道 · 无可靠答案 ${f.summary.unconfirmed_answers} 道`:esc(status[f.status]||f.status)}</p>`).join('')}</div><div class="as-actions">${b.files.filter(f=>f.paper_id).map(f=>button('打开我的试卷',`data-own-open="${esc(f.paper_id)}"`,true)).join('')}${b.files.map(f=>`<a class="as-btn" href="/api/v4/papers/imports/${encodeURIComponent(b.batch_id)}/${encodeURIComponent(f.job_id)}/original" target="_blank" rel="noopener">查看原始 PDF</a>`).join('')}${['failed','partial'].includes(b.status)?button('重试',`data-own-retry="${esc(b.batch_id)}"`)+button('删除失败任务',`data-own-delete="${esc(b.batch_id)}"`):''}</div></article>`).join('')||'<p class="as-empty">还没有上传试卷。选择上方 PDF 后，即可查看解析进度。</p>'}`;
}
function studentUploadPage(){frame(`<div class="as-hero"><h1>我的试卷</h1><p class="muted">把 PDF 原题转成练习或模考，保留原图与公式。原卷没有可靠答案时，仍可完成考试并保存作答。</p></div><section class="as-panel"><h2>导入 PDF</h2><form id="student-import" class="as-form"><div class="as-dropzone" data-pdf-drop><strong>将 PDF 拖到这里</strong><span>或选择电脑中的文件</span><label class="as-btn" for="student-pdf">选择 PDF 文件</label><input id="student-pdf" class="as-file-input" name="file" type="file" accept=".pdf,application/pdf" aria-label="PDF 试卷"><small>每次一份，最大 50 MiB</small><p data-file-state role="status">尚未选择文件</p></div><div class="as-grid"><label>试卷名称<input name="title" required value="我的 MCQ 试卷" maxlength="200"></label><label>考试时间（分钟）<input name="duration_minutes" type="number" min="0.1" max="600" step="0.1" value="45" required></label></div><label>课程<select name="course_id"><option value="${esc(registry.course_id)}">AP Physics C: Mechanics</option></select></label><div><button class="as-btn primary" data-upload-submit>上传并解析</button><div class="as-upload-progress" data-upload-progress hidden><progress max="100" value="0" aria-label="PDF 上传进度"></progress><p role="status" data-upload-state></p></div></div><small>你的试卷仅自己可见。仅使用可靠匹配的原卷答案评分；无答案时成绩保持未知。</small></form></section><section id="own-import-jobs" class="as-panel">${ownJobsHTML()}</section>`,'exam/upload');}
async function refreshOwnImports(){ownImports=await request('/papers/imports');const root=document.getElementById('own-import-jobs');if(root){root.innerHTML=ownJobsHTML();bindOwnJobs();}}
function bindStudentImport(){
 const form=document.getElementById('student-import');if(form){const selected=bindPDFPicker(form);form.onsubmit=e=>{e.preventDefault();act(async()=>{
  const file=selected(),f=new FormData(form);f.set('file',file);form.dataset.requestKey=form.dataset.requestKey||crypto.randomUUID();f.set('request_key',form.dataset.requestKey);
  const submit=form.querySelector('[data-upload-submit]'),progress=form.querySelector('[data-upload-progress]'),bar=progress.querySelector('progress'),note=progress.querySelector('[data-upload-state]');submit.disabled=true;progress.hidden=false;bar.value=0;note.textContent='正在上传 PDF…';
  try{await uploadPDF(f,n=>{bar.value=n;note.textContent=n===100?'上传完成，正在保存解析任务…':'正在上传 '+n+'%';});form.dataset.requestKey='';await refreshOwnImports();studentUploadPage();say('PDF 已保存，正在后台解析；进度会自动更新。');}
  catch(error){note.textContent=error.message;throw error;}finally{submit.disabled=false;}
 });};}bindOwnJobs();
}
function bindOwnJobs(){
 for(const b of document.querySelectorAll('[data-own-delete]'))b.onclick=()=>{const d=document.createElement('dialog');d.innerHTML=`<h2>删除失败任务？</h2><p>只从列表移除这条失败任务。原始 PDF、解析诊断和已有作答都会保留。</p><div class="as-actions">${button('取消','data-close')}${button('确认删除','data-delete-confirm',true)}</div>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>{d.close();d.remove();};d.querySelector('[data-delete-confirm]').onclick=()=>act(async()=>{await request('/papers/imports/'+b.dataset.ownDelete,{method:'DELETE'});d.close();d.remove();await refreshOwnImports();say('任务已从列表移除，原文件与作答保留。');});d.showModal();};
 document.querySelector('[data-own-refresh]')?.addEventListener('click',()=>act(refreshOwnImports));
 for(const b of document.querySelectorAll('[data-own-retry]'))b.onclick=()=>act(async()=>{await request('/papers/imports/'+b.dataset.ownRetry+'/retry',{method:'POST'});await refreshOwnImports();});
for(const b of document.querySelectorAll('[data-own-open]'))b.onclick=()=>act(async()=>{papers=await request('/sets');const paper=papers.find(p=>p.set_id===b.dataset.ownOpen);if(!paper)throw Error('试卷仍在解析，请稍后刷新');const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(paper.title)}</h2><p>${paper.question_count} 道 MCQ · ${paper.duration_minutes} 分钟</p><p>选择不计时练习，或开始独立倒计时的正式模考。</p><div class="as-actions">${button('自由练习我的试卷','data-own-practice')}${button('正式模拟考试','data-own-exam',true)}${button('取消','data-close')}</div>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>{d.close();d.remove();};d.querySelector('[data-own-exam]').onclick=()=>{d.close();d.remove();examReady(paper.set_id);};d.querySelector('[data-own-practice]').onclick=()=>act(async()=>{const s=await request('/sessions',{method:'POST',body:{mode:'practice',paper_id:paper.set_id,request_id:crypto.randomUUID(),count:200,context:context()}});d.close();d.remove();openSession(s);});d.showModal();});}
init().catch(e=>say(e.message));
setInterval(()=>{if(!busy&&!document.hidden&&location.hash==='#exam/upload'&&ownImports.some(b=>['queued','running'].includes(b.status)))act(refreshOwnImports);},2500);
